-- Conflict Converge - Premake5 Configuration
-- Build system for raylib-based RTS game
-- Generated by premake5

workspace "ConflictConverge"
    configurations { "Debug", "Release" }
    
    -- Output directory  
    location "prj"

-- Project to build raylib as static library from deps/
project "raylib-static"
    kind "StaticLib"
    cppdialect "C++20"
    
    -- Source files from raylib source in deps/
    files {
        "deps/raylib/src/**.c",
        "deps/raylib/src/**.h",
        "deps/raylib/src/**.inl"
    }
    
    -- Include directories for raylib's own dependencies
    includedirs {
        "deps/raylib/include",
        "deps/glm/glm"
    }
    
    -- Link with glm
    links { "glm" }

-- Project to build raygui as static library from deps/
project "raygui-static"
    kind "StaticLib"
    cppdialect "C++20"
    
    -- Source files from raygui source in deps/
    files {
        "deps/raygui/src/**.c",
        "deps/raygui/src/**.h",
        "deps/raygui/src/**.inl"
    }
    
    -- Include directories for raygui's dependencies (raylib and glm)
    includedirs {
        "deps/raylib/include",
        "deps/glm/glm"
    }

-- Main game project
project "conflict-converge"
    kind "ConsoleApp"
    cppdialect "C++20"
    
    -- Source files from src/ folder
    files {
        "src/**.cpp",
        "src/**.h",
        "src/**.inl"
    }
    
    -- Include directories
    includedirs {
        "deps/raylib/src",
        "deps/raygui/src",
        "deps/glm/glm",
        "..",
        "src/game"
    }
    
    -- Link with raylib and raygui static libraries
    links {
        "raylib-static",
        "raygui-static"
    }

-- Test project
project "conflict-converge-test"
    kind "ConsoleApp"
    cppdialect "C++20"
    
    -- Depend on conflict-converge project (build order dependency)
    dependson { "conflict-converge" }
    
    -- Source files from tests/ folder
    files {
        "tests/**.cpp",
        "tests/**.h",
        "tests/**.inl"
    }
    
    -- Include directories
    includedirs {
        "deps/raylib/src",
        "deps/raygui/src",
        "deps/glm/glm",
        "..",
        "src/game/public"
    }
    
    -- Link with raylib and raygui static libraries
    links {
        "raylib-static",
        "raygui-static"
    }
